    &lt;DataSourceRefreshType&gt;manual&lt;/DataSourceRefreshType&gt;
    &lt;DateFormat&gt;m/d/yy&lt;/DateFormat&gt;
    &lt;ItemButtonGroups&gt;[]&lt;/ItemButtonGroups&gt;
    &lt;GridButtonGroups&gt;[]&lt;/GridButtonGroups&gt;
    &lt;ItemButtons&gt;[]&lt;/ItemButtons&gt;
    &lt;GridButtons&gt;[{&quot;EnableSelection&quot;:false,&quot;RequiresSelection&quot;:false,&quot;RequiresData&quot;:false,&quot;ShowCount&quot;:false,&quot;SumColumn&quot;:null,&quot;SumMode&quot;:&quot;Default&quot;,&quot;SumCoefficient&quot;:null,&quot;TextBeforeSum&quot;:null,&quot;TextAfterSum&quot;:null,&quot;ConfirmationPosition&quot;:&quot;centered&quot;,&quot;VerticalPosition&quot;:&quot;Bottom&quot;,&quot;HorizontalPosition&quot;:&quot;Right&quot;,&quot;BulkActions&quot;:[{&quot;Id&quot;:-1,&quot;IsDeleted&quot;:false,&quot;ActionInfo&quot;:{&quot;Id&quot;:-1,&quot;GlobalId&quot;:&quot;e19e0186-3e9b-4a74-99d0-de4bb01bbf44&quot;,&quot;Description&quot;:&quot;Export Calcul Lichidare in .xls&quot;,&quot;ActionErrorMessage&quot;:null,&quot;ActionStackId&quot;:-1,&quot;ActionType&quot;:&quot;ExcelFromEntityList&quot;,&quot;Condition&quot;:null,&quot;IsDeleted&quot;:false,&quot;IsDisabled&quot;:false,&quot;OrderIndex&quot;:0,&quot;DiagramUID&quot;:null,&quot;ActionParameters&quot;:null,&quot;Parameters&quot;:{&quot;SpecialSerializationConditions&quot;:null,&quot;EntityName&quot;:null,&quot;Fields&quot;:null,&quot;IncludeAllFields&quot;:true,&quot;RemoveFieldNames&quot;:false,&quot;UseFormulas&quot;:false,&quot;Criteria&quot;:null,&quot;Pattern&quot;:&quot;CalculLichidare_[GetOrSession:MonthV]_[GetOrSession:YearV]_[GetOrSession:BranchV]&quot;,&quot;Duplicates&quot;:{&quot;IsExpression&quot;:false,&quot;Expression&quot;:&quot;&quot;,&quot;Value&quot;:&quot;Overwrite&quot;},&quot;FilePassword&quot;:null,&quot;WorksheetPassword&quot;:null,&quot;Folder&quot;:{&quot;IsExpression&quot;:false,&quot;Expression&quot;:&quot;&quot;,&quot;Value&quot;:&quot;/Export&quot;},&quot;StoreAbsoluteURL&quot;:null,&quot;StoreRelativeURL&quot;:null,&quot;StorePhysicalPath&quot;:null,&quot;StoreLinkClick&quot;:&quot;ExcelURL&quot;,&quot;DisableForceDownload&quot;:false},&quot;Metadata&quot;:{},&quot;HasActionParameters&quot;:true}},{&quot;Id&quot;:-1,&quot;IsDeleted&quot;:false,&quot;ActionInfo&quot;:{&quot;Id&quot;:-1,&quot;GlobalId&quot;:&quot;5ae8d327-51a8-4222-ab54-733fe5d8d14d&quot;,&quot;Description&quot;:null,&quot;ActionErrorMessage&quot;:null,&quot;ActionStackId&quot;:-1,&quot;ActionType&quot;:&quot;RedirectToUrl&quot;,&quot;Condition&quot;:null,&quot;IsDeleted&quot;:false,&quot;IsDisabled&quot;:false,&quot;OrderIndex&quot;:1,&quot;DiagramUID&quot;:null,&quot;ActionParameters&quot;:null,&quot;Parameters&quot;:{&quot;Url&quot;:&quot;[ExcelURL]&quot;,&quot;EscapeUrl&quot;:false,&quot;OpenInPopup&quot;:false,&quot;PopupTitle&quot;:null,&quot;OpenInNewTab&quot;:false,&quot;ForceDownload&quot;:true},&quot;Metadata&quot;:{},&quot;HasActionParameters&quot;:true}}],&quot;BulkActionsAfter&quot;:[],&quot;ItemActions&quot;:[],&quot;OnItemClickActionStackId&quot;:-1,&quot;OnBulkClickActionStackId&quot;:-1,&quot;OnBulkClickAfterActionStackId&quot;:-1,&quot;Url&quot;:&quot;&amp;amp;buttonName=ExportCalculLichidare&quot;,&quot;ModuleId&quot;:927,&quot;AutoName&quot;:true,&quot;Name&quot;:&quot;ExportCalculLichidare&quot;,&quot;Title&quot;:&quot;Export Calcul Lichidare&quot;,&quot;Help&quot;:null,&quot;ShowCondition&quot;:&quot;([HasRole:Admins] || [HasRole:CitizenDevelopers] || [HasRole:Low-CodeEngineer] || [HasRole:Managers] || [HasRole:Payroll_Operator] || [HasRole:Users])&quot;,&quot;IsEnabled&quot;:false,&quot;Metadata&quot;:{},&quot;Type&quot;:&quot;GridButton&quot;,&quot;OrderIndex&quot;:0,&quot;CssClass&quot;:&quot;link&quot;,&quot;CustomCssClass&quot;:null,&quot;IconClass&quot;:null,&quot;FaIconClass&quot;:null,&quot;PermissionAllUsers&quot;:false,&quot;PermissionsExportJson&quot;:&quot;[\&quot;Managers\&quot;,\&quot;Admins\&quot;,\&quot;Citizen Developers\&quot;,\&quot;Low-Code Engineer\&quot;,\&quot;Payroll_Operator\&quot;,\&quot;Users\&quot;]&quot;,&quot;Permissions&quot;:[8,6,7,5,13,9],&quot;AskForConfirmation&quot;:false,&quot;ConfirmationMessage&quot;:&quot;Are you sure you want to do this?&quot;,&quot;ConfirmationOk&quot;:&quot;Yes, pretty sure&quot;,&quot;ConfirmationCancel&quot;:&quot;No, I&#39;m having second thoughts&quot;,&quot;JsCode&quot;:null,&quot;IsClientButton&quot;:false,&quot;ButtonGroupId&quot;:null,&quot;ButtonGroupName&quot;:null,&quot;Id&quot;:0,&quot;EnableCondition&quot;:null,&quot;IsDeleted&quot;:false},{&quot;EnableSelection&quot;:false,&quot;RequiresSelection&quot;:false,&quot;RequiresData&quot;:false,&quot;ShowCount&quot;:false,&quot;SumColumn&quot;:null,&quot;SumMode&quot;:&quot;Default&quot;,&quot;SumCoefficient&quot;:null,&quot;TextBeforeSum&quot;:null,&quot;TextAfterSum&quot;:null,&quot;ConfirmationPosition&quot;:&quot;centered&quot;,&quot;VerticalPosition&quot;:&quot;Top&quot;,&quot;HorizontalPosition&quot;:&quot;Right&quot;,&quot;BulkActions&quot;:[{&quot;Id&quot;:-1,&quot;IsDeleted&quot;:false,&quot;ActionInfo&quot;:{&quot;Id&quot;:-1,&quot;GlobalId&quot;:&quot;dd785052-014a-4c17-8915-edcde60af513&quot;,&quot;Description&quot;:&quot;Calcul Lichidare&quot;,&quot;ActionErrorMessage&quot;:null,&quot;ActionStackId&quot;:-1,&quot;ActionType&quot;:&quot;RunSql&quot;,&quot;Condition&quot;:&quot;0&quot;,&quot;IsDeleted&quot;:false,&quot;IsDisabled&quot;:false,&quot;OrderIndex&quot;:0,&quot;DiagramUID&quot;:null,&quot;ActionParameters&quot;:null,&quot;Parameters&quot;:{&quot;DbConnector&quot;:{&quot;Type&quot;:&quot;Database&quot;,&quot;Group&quot;:&quot;&quot;,&quot;EntireGroup&quot;:false},&quot;ConnectionString&quot;:null,&quot;QueryTimeout&quot;:null,&quot;SqlQuery&quot;:&quot;/*=====================================================
    0️⃣ Declarare Statusuri
=====================================================*/
DECLARE @StatusDraft INT
DECLARE @StatusBlocat INT
DECLARE @StatusConfirmat INT

SELECT @StatusDraft = Id
FROM app.StatusCalcul
WHERE Denumire = &#39;Draft&#39;

SELECT @StatusBlocat = Id
FROM app.StatusCalcul
WHERE Denumire = &#39;Blocat&#39;

SELECT @StatusConfirmat = Id
FROM app.StatusCalcul
WHERE Denumire = &#39;Confirmat&#39;


/*=====================================================
    1️⃣ ControlLichidare
=====================================================*/
IF NOT EXISTS
(
    SELECT 1
    FROM app.ControlLichidare
    WHERE Anul = @Anul
      AND Luna = @Luna
      AND CodSucursala = @CodSucursala
)
BEGIN

    INSERT INTO app.ControlLichidare
    (
        Anul,
        Luna,
        CodSucursala,
        Status,
        CreatDe,
        DataCreare
    )
    VALUES
    (
        @Anul,
        @Luna,
        @CodSucursala,
        @StatusDraft,
        @UserName,
        GETDATE()
    )

END


/*=====================================================
    2️⃣ Validare
=====================================================*/
DECLARE @StatusCurent INT

SELECT @StatusCurent = Status
FROM app.ControlLichidare
WHERE Anul = @Anul
  AND Luna = @Luna
  AND CodSucursala = @CodSucursala

IF @StatusCurent IS NULL
BEGIN
    RAISERROR (&#39;Nu exista ControlLichidare.&#39;,16,1)
    RETURN
END

IF @StatusCurent = @StatusBlocat
BEGIN
    RAISERROR (&#39;Luna este blocata.&#39;,16,1)
    RETURN
END


/*=====================================================
    3️⃣ Reset calcul
=====================================================*/
DELETE FROM app.CalculLichidare
WHERE Anul = @Anul
  AND Luna = @Luna
  AND CodSucursala = @CodSucursala


/*=====================================================
    4️⃣ Parametri
=====================================================*/
;WITH Parametri AS
(
    SELECT
        [Initializari:ZileLucratoare_old(
            Anul = [GetOrSession:YearV],
            Luna = [GetOrSession:MonthV]
        )] AS ZileLucratoare
)


/*=====================================================
    5️⃣ Insert CalculLichidare
=====================================================*/
INSERT INTO app.CalculLichidare
(
    IdSalariat,
    CodSucursala,
    Marca,
    TipNorma,

    ZileLucratoare,
    ZileCO,
    ZileCM,
    ZileLucrate,

    OreLucrate,

    SalariuBrut,
	ValPeZi,
    ProcentLoialitate,
    ValoareLoialitate,

    SalBrutEfectiv,

    ValoareCO,
    ValoareCM,

    TicheteMasa,

    Agenti,
    Remiza,

    IndemnizatieConducere,
    IndemnizatieCFP,

    ProcentContinuitate,
    ValoareContinuitate,

    IndemnizatieProgramFractionat,

    AlteDrepturi,

    BrutContributiv,
    TotalBrut,

    CAS,
    CASS,
    CAM,

    BazaImpozabila,
    ImpozitVenit,

    CAR,
    PensiiAlimentare,
    PensiiFacultative,

    Chirii,
    Casa,
    Banca,
    Garantii,
    Popriri,
    Imputatii,

    TotalRetineri,

    VenitNet,
    SalariuNet,
    NetDePlata,

    Anul,
    Luna,

    DataCalcul,

    Status
)

SELECT

    /*========================================
        Identificare
    ========================================*/
    a.Id,
    @CodSucursala,
    a.Marca,
    a.TipNorma,


    /*========================================
        Zile
    ========================================*/
    p.ZileLucratoare,

    ISNULL(co.ZileCOLuna,0),

    ISNULL(cm.ZileCMLuna,0),

    zl.ZileLucrate,


    /*========================================
        Ore
    ========================================*/
    ca1.OreLucrate,


    /*========================================
        Salariu baza
    ========================================*/
    b.Salariu,
    ca1.ValPeZi,


    /*========================================
        Loialitate
    ========================================*/
    ISNULL(a.ProcentLoialitate,0.00),

    ca1.ValoareLoialitate,


    /*========================================
        Bruturi
    ========================================*/
    ca1.SalBrutEfectiv,

    ca1.ValoareCO,

    ca1.ValoareCM,


    /*========================================
        Tichete
    ========================================*/
    ca1.TicheteTotale,


    /*========================================
        Sporuri
    ========================================*/
    ISNULL(ag.SumaAgent,0),

    ISNULL(rem.Sume_Remiza,0),

    ISNULL(a.IndemnizatieConducere,0),

    ISNULL(a.IndemnizatieCFP,0),

    ISNULL(a.ProcentContinuitate,0.00),

    ca1.ValoareContinuitate,

    ISNULL(a.IndemnizatieProgramFractionat,0),

    0,


    /*========================================
        BazaCalculAsigurare
    ========================================*/
    ba.BrutContributiv,

    ca2.TotalBrut,

    ba.CAS,

    ba.CASS,

    ba.CAM,

    ba.BazaImpozabila,

    ba.Impozit,


    /*========================================
        Retineri
    ========================================*/
    ISNULL(car2.CAR,0),

    ISNULL(pa.PensiiAlimentare,0),

    ISNULL(ret.PensiiFacultative,0),

    ISNULL(ret.Chirii,0),

    ISNULL(ret.Casa,0),

    ISNULL(ret.Banca,0),

    0,

    ISNULL(pop.Popriri,0),

    ISNULL(imp.Imputatii,0),

    tr.TotalRetineri,


    /*========================================
        Net
    ========================================*/
    ca4.VenitNet,

    ca4.SalariuNet,

    CASE
        WHEN ca4.SalariuNet - tr.TotalRetineri &amp;lt; 0
        THEN 0

        ELSE ca4.SalariuNet - tr.TotalRetineri
    END,


    /*========================================
        Audit
    ========================================*/
    @Anul,

    @Luna,

    GETDATE(),

    @StatusDraft


FROM app.Salariat a


/******************************************************
    SALARIU
******************************************************/
LEFT JOIN app.NomGrilaSalarizare b
    ON b.Clasa = a.Clasa
   AND b.TipMediu = &#39;U&#39;


/******************************************************
    TICHETE
******************************************************/
LEFT JOIN app.TSTichetMasa t
    ON t.Anul = @Anul
   AND t.Luna = @Luna


/******************************************************
    BAZA CALCUL ASIGURARE
******************************************************/
LEFT JOIN app.BazaCalculAsigurare ba
    ON ba.Marca = a.Marca
   AND ba.Anul = @Anul
   AND ba.Luna = @Luna
   AND ba.CodSucursala = @CodSucursala


CROSS JOIN Parametri p


/******************************************************
    CO
******************************************************/
OUTER APPLY
(
    SELECT
        SUM(

            CASE
                WHEN MONTH(c.Interval1DatadeInceput)=@Luna
                 AND YEAR(c.Interval1DatadeInceput)=@Anul
                THEN ISNULL(c.NrZileCO1,0)
                ELSE 0
            END

            +

            CASE
                WHEN MONTH(c.Interval2DatadeInceput)=@Luna
                 AND YEAR(c.Interval2DatadeInceput)=@Anul
                THEN ISNULL(c.NrZileCO2,0)
                ELSE 0
            END

            +

            CASE
                WHEN MONTH(c.Interval3DatadeInceput)=@Luna
                 AND YEAR(c.Interval3DatadeInceput)=@Anul
                THEN ISNULL(c.NrZileCO3,0)
                ELSE 0
            END

        ) AS ZileCOLuna

    FROM app.ConcediudeOdihna c

    WHERE c.Marca = a.Marca
      AND c.CodSucursala = @CodSucursala

) co


/******************************************************
    CM
******************************************************/
OUTER APPLY
(
    SELECT
        SUM(m.TotZileLucratoare) AS ZileCMLuna

    FROM app.ConcediuMedical m

    WHERE m.Marca = a.Marca
      AND m.CodSucursala = @CodSucursala
      AND m.AnulDePlata = @Anul
      AND m.LunaDePlata = @Luna

) cm


/******************************************************
    ZILE LUCRATE
******************************************************/
CROSS APPLY
(
    SELECT

        CASE

            WHEN p.ZileLucratoare
                 - ISNULL(co.ZileCOLuna,0)
                 - ISNULL(cm.ZileCMLuna,0) &amp;lt; 0

            THEN 0

            ELSE
                p.ZileLucratoare
                - ISNULL(co.ZileCOLuna,0)
                - ISNULL(cm.ZileCMLuna,0)

        END AS ZileLucrate

) zl


/******************************************************
    SPORURI
******************************************************/
OUTER APPLY
(
    SELECT
        SUM(ISNULL(Suma,0)) AS SumaAgent

    FROM app.CalculAgent

    WHERE Marca = a.Marca
      AND Anul = @Anul
      AND Luna = @Luna
      AND CodSucursala = @CodSucursala

) ag


OUTER APPLY
(
    SELECT
        SUM(ISNULL(Suma,0)) AS Sume_Remiza

    FROM app.Remiza

    WHERE Marca = a.Marca
      AND Anul = @Anul
      AND Luna = @Luna
      AND CodSucursala = @CodSucursala

) rem


/******************************************************
    RETINERI
******************************************************/
OUTER APPLY
(
    SELECT
        SUM(ISNULL(RataLunara,0)) AS CAR

    FROM app.CAR

    WHERE Marca = a.Marca
      AND Anul = @Anul
      AND Luna = @Luna
      AND CodSucursala = @CodSucursala

) car2


OUTER APPLY
(
    SELECT
        SUM(
            ISNULL(Rata,0)
            + ISNULL(Rest,0)
            + ISNULL(Taxa,0)
            + ISNULL(Taxam,0)
        ) AS PensiiAlimentare

    FROM app.PensieAlimentara

    WHERE Marca = a.Marca
      AND Anul = @Anul
      AND Luna = @Luna
      AND CodSucursala = @CodSucursala

) pa


OUTER APPLY
(
    SELECT
        SUM(
            ISNULL(Rata,0)
            + ISNULL(Dobanda,0)
            + ISNULL(Restanta,0)
        ) AS Imputatii

    FROM app.Imputatie

    WHERE Marca = a.Marca
      AND Anul = @Anul
      AND Luna = @Luna
      AND CodSucursala = @CodSucursala

) imp


OUTER APPLY
(
    SELECT
        SUM(
            ISNULL(Rata,0)
            + ISNULL(Dobanda,0)
            + ISNULL(Restanta,0)
        ) AS Popriri

    FROM app.Poprire

    WHERE Marca = a.Marca
      AND Anul = @Anul
      AND Luna = @Luna
      AND CodSucursala = @CodSucursala

) pop


OUTER APPLY
(
    SELECT

        SUM(
            CASE WHEN TipRata=1
                 THEN Rata+Dobanda+RestDePlata
                 ELSE 0
            END
        ) AS Chirii,

        SUM(
            CASE WHEN TipRata=2
                 THEN Rata+Dobanda+RestDePlata
                 ELSE 0
            END
        ) AS Casa,

        SUM(
            CASE WHEN TipRata=3
                 THEN Rata+Dobanda+RestDePlata
                 ELSE 0
            END
        ) AS Banca,

        SUM(
            CASE WHEN TipRata=7
                 THEN Rata+Dobanda+RestDePlata
                 ELSE 0
            END
        ) AS PensiiFacultative

    FROM app.Retinere

    WHERE Marca = a.Marca
      AND Anul = @Anul
      AND Luna = @Luna
      AND CodSucursala = @CodSucursala

) ret


CROSS APPLY
(
    SELECT

        ISNULL(car2.CAR,0)

        + ISNULL(ret.Chirii,0)

        + ISNULL(ret.Casa,0)

        + ISNULL(ret.Banca,0)

        + ISNULL(pop.Popriri,0)

        + ISNULL(imp.Imputatii,0)

        + ISNULL(pa.PensiiAlimentare,0)

        + ISNULL(ret.PensiiFacultative,0)

        AS TotalRetineri

) tr


/******************************************************
    CALCUL
******************************************************/
CROSS APPLY
(
    SELECT

        CAST(
            b.Salariu / NULLIF(CAST(p.ZileLucratoare AS DECIMAL(18,6)),0)
        AS DECIMAL(18,6)) AS ValPeZi,

        zl.ZileLucrate * a.TipNorma * 8 AS OreLucrate,

        ROUND(
            (b.Salariu / NULLIF(p.ZileLucratoare,0))
            * zl.ZileLucrate
        ,0) AS SalBrutEfectiv,

 ROUND(
    ROUND(
        CAST(
            b.Salariu
            / NULLIF(CAST(p.ZileLucratoare AS DECIMAL(18,6)),0)
        AS DECIMAL(18,6))
    ,2)

    * CAST(zl.ZileLucrate AS DECIMAL(18,2))

    * CAST(ISNULL(a.ProcentLoialitate,0) AS DECIMAL(10,9))

,0) AS ValoareLoialitate,

        ROUND(
            (
                (b.Salariu / NULLIF(p.ZileLucratoare,0))
                * zl.ZileLucrate
            )
            * ISNULL(a.ProcentContinuitate,0)
        ,0) AS ValoareContinuitate,


        ROUND(
            (b.Salariu / NULLIF(p.ZileLucratoare,0))
            * ISNULL(co.ZileCOLuna,0)
        ,0) AS ValoareCO,


        ROUND(
            (b.Salariu / NULLIF(p.ZileLucratoare,0))
            * ISNULL(cm.ZileCMLuna,0)
            * 0.75
        ,0) AS ValoareCM,


        ISNULL(t.Valoare,0)
        * zl.ZileLucrate AS TicheteTotale

) ca1


/******************************************************
    TOTAL BRUT
******************************************************/
CROSS APPLY
(
    SELECT

        ba.BrutContributiv

        + ca1.TicheteTotale

        AS TotalBrut

) ca2


/******************************************************
    NET
******************************************************/
CROSS APPLY
(
    SELECT

        (
            ba.BrutContributiv
            - ba.CAS
            - ba.CASS
            - ba.Impozit
        ) AS SalariuNet,

        (
            ba.BrutContributiv
            - ba.CAS
            - ba.CASS
            - ba.Impozit
        ) AS VenitNet

) ca4


/******************************************************
    FILTRU
******************************************************/
WHERE a.CodSucursala = @CodSucursala
  AND a.Anul = @Anul
  AND a.Luna = @Luna


/*=====================================================
    6️⃣ Update Control
=====================================================*/
UPDATE CLControl
SET

    Status =
        CASE

            WHEN EXISTS
            (
                SELECT 1
                FROM app.CalculLichidare CL
                WHERE CL.Anul = CLControl.Anul
                  AND CL.Luna = CLControl.Luna
                  AND CL.CodSucursala = CLControl.CodSucursala
                  AND CL.Status &amp;lt;&amp;gt; @StatusConfirmat
            )

            THEN @StatusDraft

            ELSE @StatusConfirmat

        END,

    ModificatDe = @UserName,

    DataModificarii = GETDATE()

FROM app.ControlLichidare CLControl

WHERE CLControl.Anul = @Anul
  AND CLControl.Luna = @Luna
  AND CLControl.CodSucursala = @CodSucursala
  AND CLControl.Status &amp;lt;&amp;gt; @StatusBlocat


/*=====================================================
    7️⃣ Exceptii UI
=====================================================*/
SELECT COUNT(*) AS NrExceptii
FROM app.CalculLichidare
WHERE Anul = @Anul
  AND Luna = @Luna
  AND CodSucursala = @CodSucursala
  AND (
        ISNULL(ZileCO,0)
        + ISNULL(ZileCM,0)
