s\&quot;,\&quot;Citizen Developers\&quot;,\&quot;Low-Code Engineer\&quot;,\&quot;Managers\&quot;]&quot;,&quot;Permissions&quot;:[13,9,6,7,5,8],&quot;AskForConfirmation&quot;:false,&quot;ConfirmationMessage&quot;:&quot;Are you sure you want to do this?&quot;,&quot;ConfirmationOk&quot;:&quot;Yes, pretty sure&quot;,&quot;ConfirmationCancel&quot;:&quot;No, I&#39;m having second thoughts&quot;,&quot;JsCode&quot;:null,&quot;IsClientButton&quot;:false,&quot;ButtonGroupId&quot;:null,&quot;ButtonGroupName&quot;:null,&quot;Id&quot;:0,&quot;EnableCondition&quot;:&quot;[Helper:TokenStatusCalculLichidare] == 1&quot;,&quot;IsDeleted&quot;:false},{&quot;EnableSelection&quot;:false,&quot;RequiresSelection&quot;:false,&quot;RequiresData&quot;:false,&quot;ShowCount&quot;:false,&quot;SumColumn&quot;:null,&quot;SumMode&quot;:&quot;Default&quot;,&quot;SumCoefficient&quot;:null,&quot;TextBeforeSum&quot;:null,&quot;TextAfterSum&quot;:null,&quot;ConfirmationPosition&quot;:&quot;centered&quot;,&quot;VerticalPosition&quot;:&quot;Top&quot;,&quot;HorizontalPosition&quot;:&quot;Right&quot;,&quot;BulkActions&quot;:[{&quot;Id&quot;:-1,&quot;IsDeleted&quot;:false,&quot;ActionInfo&quot;:{&quot;Id&quot;:-1,&quot;GlobalId&quot;:&quot;fa090589-7418-453e-9f5b-6e3bd91447ee&quot;,&quot;Description&quot;:&quot;Exceptii Prezenta&quot;,&quot;ActionErrorMessage&quot;:null,&quot;ActionStackId&quot;:-1,&quot;ActionType&quot;:&quot;ExecuteActions&quot;,&quot;Condition&quot;:&quot;&quot;,&quot;IsDeleted&quot;:false,&quot;IsDisabled&quot;:false,&quot;OrderIndex&quot;:0,&quot;DiagramUID&quot;:null,&quot;ActionParameters&quot;:null,&quot;Parameters&quot;:{&quot;ActionList&quot;:[{&quot;Id&quot;:2966,&quot;GlobalId&quot;:&quot;00000000-0000-0000-0000-000000000000&quot;,&quot;Description&quot;:&quot;Calcul Numar Exceptii (doar pentru TipExceptie=\&quot;DEPASIRE_ZILE\&quot;)&quot;,&quot;ActionErrorMessage&quot;:null,&quot;ActionStackId&quot;:4029,&quot;ActionType&quot;:&quot;RunSql&quot;,&quot;Condition&quot;:&quot;&quot;,&quot;IsDeleted&quot;:false,&quot;IsDisabled&quot;:false,&quot;OrderIndex&quot;:0,&quot;DiagramUID&quot;:null,&quot;ActionParameters&quot;:null,&quot;Parameters&quot;:{&quot;DbConnector&quot;:{&quot;Type&quot;:&quot;Database&quot;,&quot;Group&quot;:&quot;&quot;,&quot;EntireGroup&quot;:false},&quot;ConnectionString&quot;:null,&quot;QueryTimeout&quot;:null,&quot;SqlQuery&quot;:&quot;;WITH Parametri AS (
    SELECT
        [Initializari:ZileLucratoare_old(Anul = [GetOrSession:YearV],Luna = [GetOrSession:MonthV])] AS ZileLucratoare
)

SELECT COUNT(*) AS NrExceptii
FROM (
    SELECT a.Id
    FROM app.Salariat a
CROSS JOIN Parametri p
    OUTER APPLY (
    SELECT
        SUM(
            CASE
                WHEN c.Interval1DatadeInceput IS NOT NULL
                 AND MONTH(c.Interval1DatadeInceput) = @Luna
                 AND YEAR (c.Interval1DatadeInceput) = @Anul
                THEN ISNULL(c.NrZileCO1, 0)
                ELSE 0
            END
          + CASE
                WHEN c.Interval2DatadeInceput IS NOT NULL
                 AND MONTH(c.Interval2DatadeInceput) = @Luna
                 AND YEAR (c.Interval2DatadeInceput) = @Anul
                THEN ISNULL(c.NrZileCO2, 0)
                ELSE 0
            END
          + CASE
                WHEN c.Interval3DatadeInceput IS NOT NULL
                 AND MONTH(c.Interval3DatadeInceput) = @Luna
                 AND YEAR (c.Interval3DatadeInceput) = @Anul
                THEN ISNULL(c.NrZileCO3, 0)
                ELSE 0
            END
        ) AS ZileCOLuna
    FROM app.ConcediudeOdihna c
    WHERE c.Marca        = a.Marca
      AND c.CodSucursala = @CodSucursala
) co

    OUTER APPLY (
        SELECT
            SUM(m.TotZileLucratoare) AS ZileCMLuna
        FROM app.ConcediuMedical m
        WHERE m.Marca = a.Marca
          AND m.CodSucursala = @CodSucursala
          AND m.AnulDePlata = @Anul
          AND m.LunaDePlata = @Luna
    ) cm

    WHERE
        a.Anul = @Anul
        AND a.Luna = @Luna
        AND a.CodSucursala = @CodSucursala
        AND (
            p.ZileLucratoare
            - ISNULL(co.ZileCOLuna,0)
            - ISNULL(cm.ZileCMLuna,0)
        ) &amp;lt; 0
) x;&quot;,&quot;BindTokens&quot;:[{&quot;value&quot;:&quot;[GetOrSession:BranchV]&quot;,&quot;name&quot;:&quot;CodSucursala&quot;},{&quot;value&quot;:&quot;[GetOrSession:YearV]&quot;,&quot;name&quot;:&quot;Anul&quot;},{&quot;value&quot;:&quot;[GetOrSession:MonthV]&quot;,&quot;name&quot;:&quot;Luna&quot;}],&quot;OutputTokenName&quot;:&quot;p_NrExceptii&quot;,&quot;ExtractColumns&quot;:null,&quot;OnError&quot;:[],&quot;ShowErrors&quot;:false,&quot;UseTransactions&quot;:true},&quot;Metadata&quot;:{},&quot;HasActionParameters&quot;:true},{&quot;Id&quot;:2967,&quot;GlobalId&quot;:&quot;00000000-0000-0000-0000-000000000000&quot;,&quot;Description&quot;:&quot;Verificare Exceptii !=0&quot;,&quot;ActionErrorMessage&quot;:null,&quot;ActionStackId&quot;:4029,&quot;ActionType&quot;:&quot;ShowToast&quot;,&quot;Condition&quot;:&quot;[p_NrExceptii:NrExceptii] != 0&quot;,&quot;IsDeleted&quot;:false,&quot;IsDisabled&quot;:false,&quot;OrderIndex&quot;:1,&quot;DiagramUID&quot;:null,&quot;ActionParameters&quot;:null,&quot;Parameters&quot;:{&quot;Heading&quot;:&quot;Atentionare!&quot;,&quot;Message&quot;:&quot;&amp;lt;p&amp;gt;Există [p_NrExceptii] salariați cu depășiri de zile (CO + CM). Verifică lista de excepții &#238;nainte de Confirmare Calcul Lichidare.&amp;lt;/p&amp;gt;&quot;,&quot;Icon&quot;:{&quot;IsExpression&quot;:false,&quot;Expression&quot;:&quot;&quot;,&quot;Value&quot;:&quot;warning&quot;},&quot;BgColor&quot;:&quot;#2d88a6&quot;,&quot;Transition&quot;:{&quot;IsExpression&quot;:false,&quot;Expression&quot;:&quot;&quot;,&quot;Value&quot;:&quot;slide&quot;},&quot;AllowToastClose&quot;:true,&quot;CallBackJsCode&quot;:null,&quot;HideTime&quot;:&quot;10000&quot;,&quot;Stack&quot;:&quot;3&quot;,&quot;ToastPosition&quot;:{&quot;IsExpression&quot;:false,&quot;Expression&quot;:&quot;&quot;,&quot;Value&quot;:&quot;mid-center&quot;},&quot;TextAlignment&quot;:{&quot;IsExpression&quot;:false,&quot;Expression&quot;:&quot;&quot;,&quot;Value&quot;:&quot;center&quot;},&quot;ShowLoader&quo