quot;Condition&quot;:&quot;[p_NrExceptii:NrExceptii] == 0&quot;,&quot;IsDeleted&quot;:false,&quot;IsDisabled&quot;:false,&quot;OrderIndex&quot;:3,&quot;DiagramUID&quot;:null,&quot;ActionParameters&quot;:null,&quot;Parameters&quot;:{&quot;Heading&quot;:&quot;Calcul Lichidare&quot;,&quot;Message&quot;:&quot;&amp;lt;p&amp;gt;Asteptati! Se calculeaza Lichidarea!&amp;lt;/p&amp;gt;&amp;lt;p&amp;gt;Debug: NrExceptii=[p_NrExceptii]&amp;lt;br&amp;gt;&amp;lt;br&amp;gt;&amp;lt;/p&amp;gt;&quot;,&quot;Icon&quot;:{&quot;IsExpression&quot;:false,&quot;Expression&quot;:&quot;&quot;,&quot;Value&quot;:&quot;success&quot;},&quot;BgColor&quot;:&quot;#2d88a6&quot;,&quot;Transition&quot;:{&quot;IsExpression&quot;:false,&quot;Expression&quot;:&quot;&quot;,&quot;Value&quot;:&quot;slide&quot;},&quot;AllowToastClose&quot;:true,&quot;CallBackJsCode&quot;:null,&quot;HideTime&quot;:&quot;10000&quot;,&quot;Stack&quot;:&quot;3&quot;,&quot;ToastPosition&quot;:{&quot;IsExpression&quot;:false,&quot;Expression&quot;:&quot;&quot;,&quot;Value&quot;:&quot;mid-center&quot;},&quot;TextAlignment&quot;:{&quot;IsExpression&quot;:false,&quot;Expression&quot;:&quot;&quot;,&quot;Value&quot;:&quot;center&quot;},&quot;ShowLoader&quot;:true,&quot;LoaderColor&quot;:&quot;#FFFF00&quot;},&quot;Metadata&quot;:{},&quot;HasActionParameters&quot;:true}],&quot;OnError&quot;:[]},&quot;Metadata&quot;:{},&quot;HasActionParameters&quot;:true}},{&quot;Id&quot;:-1,&quot;IsDeleted&quot;:false,&quot;ActionInfo&quot;:{&quot;Id&quot;:-1,&quot;GlobalId&quot;:&quot;3de9cf67-4f02-4b00-9aa2-9e54523bd78d&quot;,&quot;Description&quot;:&quot;Confirmare Calcul Lichidare&quot;,&quot;ActionErrorMessage&quot;:null,&quot;ActionStackId&quot;:-1,&quot;ActionType&quot;:&quot;RunSql&quot;,&quot;Condition&quot;:&quot;&quot;,&quot;IsDeleted&quot;:false,&quot;IsDisabled&quot;:false,&quot;OrderIndex&quot;:1,&quot;DiagramUID&quot;:null,&quot;ActionParameters&quot;:null,&quot;Parameters&quot;:{&quot;DbConnector&quot;:{&quot;Type&quot;:&quot;Database&quot;,&quot;Group&quot;:&quot;&quot;,&quot;EntireGroup&quot;:false},&quot;ConnectionString&quot;:null,&quot;QueryTimeout&quot;:null,&quot;SqlQuery&quot;:&quot;/*=====================================================
    0️⃣ Declarare statusuri
=====================================================*/
DECLARE @IdConfirmat INT
DECLARE @IdDraft INT
DECLARE @StatusBlocat INT

SELECT @IdConfirmat = Id FROM app.StatusCalcul WHERE Denumire = &#39;Confirmat&#39;
SELECT @IdDraft     = Id FROM app.StatusCalcul WHERE Denumire = &#39;Draft&#39;
SELECT @StatusBlocat = Id FROM app.StatusCalcul WHERE Denumire = &#39;Blocat&#39;


/*=====================================================
    1️⃣ Confirmare CalculLichidare
=====================================================*/
UPDATE app.CalculLichidare
SET 
    Status = @IdConfirmat,
    LastModifiedDate = SYSDATETIMEOFFSET(),
    LastModifiedBy = @UserId
WHERE 
    CodSucursala = @CodSucursala
    AND Anul = @Anul
    AND Luna = @Luna
    AND ISNULL(Status, @IdDraft) &amp;lt;&amp;gt; @IdConfirmat;


/*=====================================================
    3️⃣ Update ControlLichidare (status + audit)
=====================================================*/
UPDATE CLControl
SET 
    Status = 
        CASE 
            WHEN EXISTS (
                SELECT 1
                FROM app.CalculLichidare CL
                WHERE 
                    CL.Anul = CLControl.Anul
                    AND CL.Luna = CLControl.Luna
                    AND CL.CodSucursala = CLControl.CodSucursala
                    AND CL.Status &amp;lt;&amp;gt; @IdConfirmat
            )
            THEN @IdDraft
            ELSE @IdConfirmat
        END,

    ModificatDe = @Username,
    DataModificarii = GETDATE()

FROM app.ControlLichidare CLControl
WHERE 
    CLControl.Anul = @Anul
    AND CLControl.Luna = @Luna
    AND CLControl.CodSucursala = @CodSucursala
